options.panelConfig:
---
anchors:
  thresholds-operstate: &thresholds-operstate
    - { color: "red", level: 0 }
    - { color: "green", level: 1 }

  thresholds-traffic: &thresholds-traffic
    - { color: "gray", level: 0 }
    - { color: "green", level: 200000 }
    - { color: "yellow", level: 500000 }
    - { color: "orange", level: 1000000 }
    - { color: "red", level: 5000000 }

  thresholds-rate-label: &thresholds-rate-label
    - { color: "white", level: 0 }

  label-config: &label-config
    separator: "replace"
    units: "bps"
    decimalPoints: 1

cellIdPreamble: "cell-"

cells:
  # spine-leaf
  "leaf11:eth1":
    dataRef: "oper-state:leaf11:Ethernet0"
    fillColor: { thresholds: *thresholds-operstate }


  "spine11:eth1":
    dataRef: "oper-state:spine11:Ethernet0"
    fillColor: { thresholds: *thresholds-operstate }


  "link_id:leaf11:eth1:spine11:eth1":
    dataRef: "leaf11:Ethernet0:out"
    strokeColor: { thresholds: *thresholds-traffic }


  "link_id:leaf11:eth1:spine11:eth1:label":
    dataRef: "leaf11:Ethernet0:out"
    label: *label-config
    labelColor: { thresholds: *thresholds-rate-label }

  "link_id:spine11:eth1:leaf11:eth1":
